function Lightbox({project, onClose}){
  const C=COLORS;
  useEffect(()=>{
    const onKey=e=>{if(e.key==="Escape")onClose();};
    document.addEventListener("keydown",onKey);
    document.body.style.overflow="hidden";
    return()=>{document.removeEventListener("keydown",onKey);document.body.style.overflow="";};
  },[onClose]);
  return(
    <div onClick={e=>e.target===e.currentTarget&&onClose()}
      style={{position:"fixed",inset:0,zIndex:500,background:"rgba(0,0,0,0.92)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      {/* Close */}
      <button onClick={onClose} style={{position:"absolute",top:20,right:20,background:"rgba(255,255,255,0.1)",border:"1px solid rgba(255,255,255,0.2)",color:"#fff",width:44,height:44,fontSize:18,cursor:"pointer",backdropFilter:"blur(8px)",transition:"background 0.2s"}}
        onMouseEnter={e=>e.currentTarget.style.background="rgba(255,255,255,0.2)"}
        onMouseLeave={e=>e.currentTarget.style.background="rgba(255,255,255,0.1)"}>✕</button>
      {/* Image container */}
      <div style={{maxWidth:1000,width:"100%",display:"flex",flexDirection:"column",gap:0}}>
        <div style={{position:"relative",overflow:"hidden"}}>
          <img src={IMG[project.img]} alt={project.title}
            style={{width:"100%",maxHeight:"72vh",objectFit:"cover",display:"block"}}/>
          {/* Info overlay */}
          <div style={{position:"absolute",bottom:0,left:0,right:0,background:"linear-gradient(to top,rgba(0,0,0,0.85) 0%,transparent 100%)",padding:"40px 32px 24px"}}>
            <div style={{display:"flex",alignItems:"flex-end",justifyContent:"space-between",gap:16}}>
              <div>
                <span style={{fontFamily:"monospace",fontSize:9,letterSpacing:"0.2em",textTransform:"uppercase",background:"rgba(255,255,255,0.15)",color:"#fff",padding:"3px 10px",border:"1px solid rgba(255,255,255,0.2)",display:"inline-block",marginBottom:8}}>{project.category}</span>
                <h3 style={{fontSize:24,fontWeight:800,letterSpacing:"-0.02em",textTransform:"uppercase",color:"#fff",margin:"0 0 4px",lineHeight:1.1}}>{project.title}</h3>
                <p style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.15em",color:"rgba(255,255,255,0.6)",margin:0}}>📍 {project.location} · {project.size} · {project.year}</p>
              </div>
              <div style={{display:"flex",gap:10,flexShrink:0}}>
                <span style={{fontFamily:"monospace",fontSize:9,color:"rgba(255,255,255,0.4)",letterSpacing:"0.1em"}}>ESC para fechar</span>
              </div>
            </div>
          </div>
        </div>
        {/* Bottom bar */}
        <div style={{background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",padding:"16px 24px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:16,backdropFilter:"blur(12px)"}}>
          <p style={{fontSize:12,color:"rgba(255,255,255,0.7)",fontWeight:300,lineHeight:1.6,margin:0,flex:1}}>{project.description}</p>
          <button onClick={onClose} style={{flexShrink:0,background:"#fff",color:C.dark,border:"none",padding:"11px 20px",fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer"}}>Fechar ✕</button>
        </div>
      </div>
    </div>
  );
}

function PortfolioCard({project,onClick,onLightbox}){
  const [hov,setHov]=useState(false);
  return(
    <div onClick={()=>onClick(project)} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{background:COLORS.bgLight,border:`1px solid ${hov?COLORS.dark:COLORS.border}`,cursor:"pointer",transform:hov?"translateY(-6px)":"none",boxShadow:hov?"0 20px 48px rgba(30,28,26,0.12)":"none",transition:"all 0.4s cubic-bezier(0.16,1,0.3,1)",overflow:"hidden"}}>
      <div onClick={e=>{e.stopPropagation();if(onLightbox)onLightbox(project);}} style={{position:"relative",paddingTop:"66%",overflow:"hidden",cursor:"zoom-in"}}>
        <img src={IMG[project.img]} alt={project.title} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",transition:"transform 0.6s ease",transform:hov?"scale(1.06)":"scale(1)"}}/>
        <div style={{position:"absolute",inset:0,background:hov?"linear-gradient(to top,rgba(30,28,26,0.6) 0%,transparent 55%)":"transparent",transition:"all 0.4s"}}/>
        <span style={{position:"absolute",top:10,left:10,fontFamily:"monospace",fontSize:9,letterSpacing:"0.15em",textTransform:"uppercase",fontWeight:700,background:hov?COLORS.dark:"rgba(250,249,246,0.95)",color:hov?"#f5c071":COLORS.dark,padding:"4px 10px",border:`1px solid ${hov?COLORS.dark:COLORS.border}`,transition:"all 0.4s"}}>{project.category}</span>
        {hov&&<div style={{position:"absolute",top:"50%",left:"50%",transform:"translate(-50%,-50%)",background:"rgba(0,0,0,0.6)",border:"1px solid rgba(255,255,255,0.3)",padding:"8px 14px",display:"flex",alignItems:"center",gap:6,backdropFilter:"blur(4px)"}}>
          <span style={{fontSize:14}}>🔍</span>
          <span style={{fontFamily:"monospace",fontSize:8,textTransform:"uppercase",letterSpacing:"0.15em",color:"#fff",fontWeight:700}}>Ver foto</span>
        </div>}
      </div>
      <div style={{padding:"20px 22px"}}>
        <p style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.12em",color:"#a8a29e",margin:"0 0 6px"}}>📍 {project.location}</p>
        <h4 style={{fontSize:11,textTransform:"uppercase",letterSpacing:"0.1em",fontWeight:700,color:COLORS.dark,lineHeight:1.4,margin:"0 0 8px"}}>{project.title}</h4>
        <p style={{fontSize:11,color:COLORS.stone500,lineHeight:1.6,fontWeight:300,margin:0,display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{project.description}</p>
        <div style={{marginTop:14,paddingTop:14,borderTop:`1px solid ${COLORS.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.12em",color:"rgba(30,28,26,0.45)"}}>{project.size} · {project.year}</span>
          <span style={{fontFamily:"monospace",fontSize:9,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.15em",color:COLORS.dark}}>Explorar →</span>
        </div>
      </div>
    </div>
  );
}

function ProjectModal({project,onClose,onQuote}){
  return(
    <div style={{position:"fixed",inset:0,zIndex:300,background:"rgba(30,28,26,0.88)",backdropFilter:"blur(6px)",display:"flex",alignItems:"center",justifyContent:"center",padding:20,overflowY:"auto"}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:COLORS.bgLight,maxWidth:900,width:"100%",border:`1px solid ${COLORS.border}`,position:"relative",maxHeight:"92vh",overflowY:"auto"}}>
        <button onClick={onClose} style={{position:"absolute",top:12,right:12,zIndex:10,background:COLORS.dark,color:"#fff",border:"none",padding:"8px 12px",cursor:"pointer",fontSize:12}}>✕ Fechar</button>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr"}}>
          <img src={IMG[project.img]} alt={project.title} style={{width:"100%",height:"100%",objectFit:"cover",minHeight:340,display:"block"}}/>
          <div style={{padding:"32px",display:"flex",flexDirection:"column",justifyContent:"space-between"}}>
            <div>
              <span style={{fontFamily:"monospace",fontSize:9,letterSpacing:"0.15em",textTransform:"uppercase",border:`1px solid ${COLORS.border}`,padding:"3px 9px",background:COLORS.bg}}>{project.category}</span>
              <h3 style={{fontSize:22,fontWeight:800,letterSpacing:"-0.02em",textTransform:"uppercase",color:COLORS.dark,margin:"14px 0 6px",lineHeight:1.2}}>{project.title}</h3>
              <p style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.15em",color:"rgba(30,28,26,0.55)",margin:"0 0 20px"}}>📍 {project.location} &nbsp;|&nbsp; 📅 {project.year}</p>
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",border:`1px solid ${COLORS.border}`,background:COLORS.bg,padding:"12px 0",marginBottom:20}}>
                {[["Área Útil",project.size],["Categoria",project.category],["Ano",project.year]].map(([l,v],i)=>(
                  <div key={i} style={{textAlign:"center",borderLeft:i>0?`1px solid ${COLORS.border}`:"none",padding:"0 10px"}}>
                    <p style={{fontFamily:"monospace",fontSize:8,textTransform:"uppercase",letterSpacing:"0.1em",color:"rgba(30,28,26,0.45)",margin:"0 0 3px"}}>{l}</p>
                    <p style={{fontFamily:"monospace",fontSize:11,fontWeight:700,color:COLORS.dark,margin:0}}>{v}</p>
                  </div>
                ))}
              </div>
              <p style={{fontSize:12,color:COLORS.stone500,lineHeight:1.75,fontWeight:300,margin:0}}>{project.description}</p>
            </div>
            <div style={{borderTop:`1px solid ${COLORS.border}`,paddingTop:18,display:"flex",gap:10,marginTop:20}}>
              <button onClick={()=>onQuote()} style={{flex:1,background:COLORS.dark,color:"#fff",border:"none",padding:"13px 0",fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer"}}>Orçar Semelhante</button>
              <button onClick={onClose} style={{padding:"13px 20px",background:"transparent",color:COLORS.stone500,border:`1px solid ${COLORS.border}`,fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer"}}>Fechar</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
