function ComoTrabalhamos(){
  const C=COLORS;
  const [active,setActive]=useState(0);
  const steps=[
    {num:"01",label:"Briefing",full:"Briefing & Diagnóstico de Viabilidade",prazo:"5 a 10 dias úteis",icon:"🔍",desc:"Reunião técnica aprofundada para mapear o terreno, o programa de necessidades, o orçamento disponível e os regulamentos municipais vigentes. Entregamos um relatório de viabilidade completo antes de qualquer linha ser desenhada.",items:["Análise de zoneamento e recuos obrigatórios","Mapeamento do programa de necessidades","Diagnóstico de viabilidade orçamentária","Relatório técnico de condicionantes do terreno"]},
    {num:"02",label:"Estudo de Layout",full:"Estudo de Layout & Partido Arquitetônico",prazo:"10 a 20 dias úteis",icon:"📐",desc:"Desenvolvemos o estudo preliminar com plantas esquemáticas, volumetria e orientação solar. O cliente visualiza e aprova o conceito antes do projeto executivo ser iniciado.",items:["Plantas baixas esquemáticas","Estudo volumétrico 3D","Orientação solar e ventilação cruzada","Apresentação e aprovação do partido"]},
    {num:"03",label:"Detalhamento Técnico",full:"Detalhamento Técnico Executivo",prazo:"20 a 40 dias úteis",icon:"⚙️",desc:"Elaboração completa do projeto executivo com todos os detalhes construtivos, especificações de materiais, cortes técnicos e plantas de instalações hidráulicas e elétricas.",items:["Projeto arquitetônico executivo completo","Detalhamento de esquadrias e cobertura","Projeto hidrossanitário e elétrico","Memorial descritivo e especificações técnicas"]},
    {num:"04",label:"Aprovação Legal",full:"Aprovação Legal & Regularização",prazo:"30 a 60 dias úteis",icon:"📋",desc:"Gerenciamos todo o processo burocrático junto à Prefeitura de Indaiatuba e ao CAU — do protocolo do alvará até o Habite-se — eliminando riscos de embargo ou multa.",items:["Emissão do RRT junto ao CAU","Protocolo e acompanhamento na Prefeitura","Resolução de comunique-se e exigências","Emissão do alvará de construção"]},
    {num:"05",label:"Acompanhamento",full:"Acompanhamento de Obra",prazo:"Conforme cronograma",icon:"🏗️",desc:"Visitas técnicas periódicas ao canteiro para garantir fidelidade ao projeto, qualidade de execução e conformidade com as especificações contratadas. Relatórios fotográficos a cada visita.",items:["Visitas técnicas periódicas ao canteiro","Relatórios fotográficos de avanço","Gestão de conformidade com o projeto","Interface com fornecedores e construtora"]},
  ];
  const s=steps[active];
  return(
    <section style={{padding:"80px 0",background:C.bg,borderTop:`1px solid ${C.border}`,borderBottom:`1px solid ${C.border}`}}>
      <div style={{maxWidth:1280,margin:"0 auto",padding:"0 48px"}}>
        {/* Header */}
        <div style={{textAlign:"center",marginBottom:56}}>
          <div style={{display:"inline-flex",alignItems:"center",gap:8,border:`1px solid ${C.border}`,padding:"5px 16px",marginBottom:20,background:C.bgLight}}>
            <span style={{fontSize:12}}>🔑</span>
            <span style={{fontFamily:"monospace",fontSize:9,color:C.dark,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.2em"}}>Garantia do Briefing à Chave na Mão</span>
          </div>
          <Reveal><h2 style={{fontSize:52,fontWeight:900,letterSpacing:"-0.04em",textTransform:"uppercase",color:C.dark,margin:"0 0 16px",lineHeight:1}}>Como Trabalhamos</h2></Reveal>
          <p style={{fontSize:13,color:C.stone500,lineHeight:1.75,maxWidth:640,margin:"0 auto",fontWeight:300}}>Conheça as 5 etapas cruciais que coordenamos para transformar sua visão em um projeto de alto nível legalmente blindado, térmico e milimetricamente seguro.</p>
        </div>

        {/* Timeline */}
        <div style={{position:"relative",marginBottom:48}}>
          {/* Line */}
          <div style={{position:"absolute",top:18,left:"10%",right:"10%",height:1,background:C.border,zIndex:0}}/>
          <div style={{position:"absolute",top:18,left:"10%",height:1,background:C.dark,zIndex:1,width:`${active*22.5}%`,transition:"width 0.4s ease"}}/>
          {/* Steps */}
          <div style={{display:"flex",justifyContent:"space-between",position:"relative",zIndex:2}}>
            {steps.map((st,i)=>(
              <button key={i} onClick={()=>setActive(i)} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:10,background:"none",border:"none",cursor:"pointer",flex:1}}>
                <div style={{width:36,height:36,borderRadius:"50%",border:`2px solid ${i<=active?C.dark:C.border}`,background:i===active?C.dark:i<active?"#fff":C.bgLight,display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.3s",boxShadow:i===active?"0 0 0 4px rgba(30,28,26,0.1)":"none"}}>
                  {i<active
                    ?<span style={{fontSize:12,color:C.dark}}>✓</span>
                    :<span style={{width:8,height:8,borderRadius:"50%",background:i===active?"#fff":C.border,display:"block"}}/>
                  }
                </div>
                <div style={{textAlign:"center"}}>
                  <p style={{fontFamily:"monospace",fontSize:8,textTransform:"uppercase",letterSpacing:"0.2em",color:i===active?C.dark:"rgba(30,28,26,0.4)",fontWeight:700,margin:"0 0 3px"}}>ETAPA {st.num}</p>
                  <p style={{fontSize:10,textTransform:"uppercase",letterSpacing:"0.08em",fontWeight:700,color:i===active?C.dark:C.stone500,margin:0,whiteSpace:"nowrap"}}>{st.label}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Detail card */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",border:`1px solid ${C.border}`,background:C.bgLight,overflow:"hidden"}}>
          <div style={{padding:"36px 40px",borderRight:`1px solid ${C.border}`}}>
            <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:20}}>
              <div style={{width:48,height:48,border:`1px solid ${C.border}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,background:C.bg,flexShrink:0}}>{s.icon}</div>
              <div>
                <p style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.2em",color:C.stone500,fontWeight:700,margin:"0 0 3px"}}>ETAPA {s.num}</p>
                <h3 style={{fontSize:16,fontWeight:800,textTransform:"uppercase",letterSpacing:"-0.01em",color:C.dark,margin:0,lineHeight:1.2}}>{s.full}</h3>
              </div>
            </div>
            <p style={{fontSize:12,color:C.stone500,lineHeight:1.75,fontWeight:300,margin:"0 0 20px"}}>{s.desc}</p>
            <div style={{display:"inline-flex",alignItems:"center",gap:6,border:`1px solid ${C.border}`,padding:"6px 14px",background:C.bg}}>
              <span style={{fontSize:11}}>⏱</span>
              <span style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.15em",fontWeight:700,color:C.dark}}>PRAZO: {s.prazo}</span>
            </div>
          </div>
          <div style={{padding:"36px 40px",background:C.bg}}>
            <p style={{fontFamily:"monospace",fontSize:9,textTransform:"uppercase",letterSpacing:"0.2em",color:C.stone500,fontWeight:700,marginBottom:16,borderBottom:`1px solid ${C.border}`,paddingBottom:10}}>Entregas desta Etapa</p>
            <div style={{display:"flex",flexDirection:"column",gap:12}}>
              {s.items.map((item,i)=>(
                <div key={i} style={{display:"flex",alignItems:"flex-start",gap:12}}>
                  <div style={{width:24,height:24,border:`1px solid ${C.border}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,background:C.bgLight,fontSize:10,fontWeight:700,fontFamily:"monospace",color:C.dark}}>{String(i+1).padStart(2,"0")}</div>
                  <p style={{fontSize:12,color:C.stone500,lineHeight:1.6,fontWeight:300,margin:0}}>{item}</p>
                </div>
              ))}
            </div>
            <div style={{marginTop:24,paddingTop:20,borderTop:`1px solid ${C.border}`,display:"flex",gap:10}}>
              {active<4
                ?<button onClick={()=>setActive(a=>a+1)} style={{flex:1,background:C.dark,color:"#fff",border:"none",padding:"12px 0",fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer"}}>Próxima Etapa →</button>
                :<a href="https://wa.me/5519981969559" target="_blank" rel="noopener noreferrer" style={{flex:1,background:C.dark,color:"#fff",border:"none",padding:"12px 0",fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer",textDecoration:"none",display:"flex",alignItems:"center",justifyContent:"center"}}>Iniciar Meu Projeto →</a>
              }
              {active>0&&<button onClick={()=>setActive(a=>a-1)} style={{padding:"12px 20px",background:"transparent",color:C.stone500,border:`1px solid ${C.border}`,fontSize:10,fontFamily:"monospace",fontWeight:700,letterSpacing:"0.15em",textTransform:"uppercase",cursor:"pointer"}}>←</button>}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

